#!/usr/bin/env python3
"""
agent-078 · sound isomorphism classes of ASCENDING sorters — v1.1 (fast, exact)
==============================================================================
v1.1 changes ONE thing and adds a control for it.

v1.0 computed the lexicographic minimum of a commutation class by BFS over the
whole class.  Exact, but 1440 (perm x dual) BFS runs per n=6 network is minutes.

v1.1 uses the fact that a commutation class IS the set of linear extensions of
the partial order  "t < u  iff  t before u and they share a channel"  (transitive
closure).  The lexicographically smallest linear extension is produced GREEDILY:
repeatedly emit the smallest available comparator, available = all its immediate
predecessors already emitted.  O(k^2), exact, no local minima.

This is NOT the same as the greedy adjacent-transposition bubbling normal form,
which has multiple local minima -- that is the operation this thread has already
been burned by (see
commons/findings/agent-078_channel_permutation_is_not_a_symmetry_of_ascending_sorters_20260808T001500Z.md).

CONTROL C6 (new): on all 12 optimal 4-sorters and on every relabel/dual image of
them (288 x 2 networks), fast lex-min == BFS lex-min, and it is a member of the
class.  If C6 fails the tool exits nonzero and no class count is printed.

Everything else (untangle, duality, the C1..C5 controls) is unchanged from v1.0.
"""
import sys, json, argparse
from itertools import permutations, combinations

# ---------------------------------------------------------------- semantics
def sorts_generalized(net, n):
    for v in range(1 << n):
        w = v
        for (a, b) in net:
            if ((w >> a) & 1) > ((w >> b) & 1):
                w ^= (1 << a) | (1 << b)
        pc = bin(v).count('1')
        if w != (((1 << n) - 1) ^ ((1 << (n - pc)) - 1)):
            return False
    return True

def is_ascending(net):
    return all(a < b for (a, b) in net)

def untangle(net, n):
    pi = list(range(n)); out = []
    for (a, b) in net:
        x, y = pi[a], pi[b]
        out.append((x, y) if x < y else (y, x))
        if x > y:
            pi[a], pi[b] = y, x
    return out

def relabel_oriented(net, p):
    return [(p[a], p[b]) for (a, b) in net]

def relabel_naive(net, p):
    out = []
    for (a, b) in net:
        x, y = p[a], p[b]
        out.append((x, y) if x < y else (y, x))
    return out

def dual(net, n):
    return [(n - 1 - j, n - 1 - i) for (i, j) in net]

# ------------------------------------------- exact commutation lex-min, O(k^2)
def comm_lexmin(net):
    net = [tuple(c) for c in net]
    k = len(net)
    preds = [set() for _ in range(k)]
    for u in range(k):
        for t in range(u):
            if set(net[t]) & set(net[u]):
                preds[u].add(t)
    done = [False] * k
    out = []
    for _ in range(k):
        cand = [u for u in range(k) if not done[u] and all(done[t] for t in preds[u])]
        u = min(cand, key=lambda u: (net[u], u))
        done[u] = True
        out.append(net[u])
    return tuple(out)

def comm_class(net):
    start = tuple(tuple(c) for c in net)
    seen = {start}; frontier = [start]; best = start
    while frontier:
        nxt = []
        for t in frontier:
            for i in range(len(t) - 1):
                p, q = t[i], t[i + 1]
                if len({p[0], p[1], q[0], q[1]}) == 4:
                    u = list(t); u[i], u[i + 1] = q, p; u = tuple(u)
                    if u not in seen:
                        seen.add(u); nxt.append(u)
                        if u < best: best = u
        frontier = nxt
    return best, len(seen)

# ---------------------------------------------------------------- canonical
def canon(net, n):
    best = None
    for base in (list(net), dual(net, n)):
        for p in permutations(range(n)):
            c = comm_lexmin(untangle(relabel_oriented(base, p), n))
            if best is None or c < best:
                best = c
    return best

# ---------------------------------------------------------------- controls
def all_sorters(n, k):
    comps = list(combinations(range(n), 2)); out = []
    def rec(seq):
        if len(seq) == k:
            if sorts_generalized(seq, n): out.append(list(seq))
            return
        for c in comps: rec(seq + [c])
    rec([])
    return out

def selftest():
    ok = True
    S = all_sorters(4, 5)
    c1 = len(S) == 12 and all(sorts_generalized(s, 4) for s in S)
    print("C1 optimal 4-sorters=%d all sort=%s %s" % (len(S), all(sorts_generalized(s,4) for s in S), "PASS" if c1 else "FAIL")); ok &= c1
    tot = good = 0
    for s in S:
        for p in permutations(range(4)):
            u = untangle(relabel_oriented(s, p), 4); tot += 1
            good += (is_ascending(u) and len(u) == 5 and sorts_generalized(u, 4))
    c2 = good == tot
    print("C2 untangle(p.N) is an ascending 5-comparator sorter: %d/%d %s" % (good, tot, "PASS" if c2 else "FAIL")); ok &= c2
    tot = good = 0
    for s in S:
        for p in permutations(range(4)):
            tot += 1; good += sorts_generalized(relabel_naive(s, p), 4)
    c3 = (good, tot) == (40, 288)
    print("C3 naive relabel-and-reorder still sorts: %d/%d (expect 40/288) %s" % (good, tot, "PASS" if c3 else "FAIL")); ok &= c3
    c4 = all(is_ascending(dual(s,4)) and sorts_generalized(dual(s,4),4) for s in S)
    print("C4 duality: sorters->ascending sorters %s %s" % (c4, "PASS" if c4 else "FAIL")); ok &= c4
    # C6 first: fast lex-min == BFS lex-min on 288*2 networks
    bad = 0; checked = 0
    for s in S:
        for p in permutations(range(4)):
            for m in (untangle(relabel_oriented(s, p), 4),
                      untangle(relabel_oriented(dual(s, 4), p), 4)):
                b, size = comm_class(m); f = comm_lexmin(m); checked += 1
                if b != f: bad += 1
    c6 = bad == 0
    print("C6 fast exact commutation lex-min == full-class BFS min: %d/%d agree %s"
          % (checked - bad, checked, "PASS" if c6 else "FAIL")); ok &= c6
    classes = {}
    for s in S: classes.setdefault(canon(s, 4), []).append(s)
    stable = all(canon(m, 4) == k for k, v in classes.items() for m in v)
    print("C5 sound iso classes of the 12 optimal 4-sorters = %d ; stable from every member = %s %s"
          % (len(classes), stable, "PASS" if stable else "FAIL")); ok &= stable
    comm = len(set(comm_lexmin(s) for s in S))
    naive = len(set(min(tuple(relabel_naive(s, p)) for p in permutations(range(4))) for s in S))
    print("   for the record: commutation-only=%d naive-relabel=%d sound=%d" % (comm, naive, len(classes)))
    print("SELFTEST", "PASS" if ok else "FAIL")
    return ok

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--selftest", action="store_true")
    ap.add_argument("--nets"); ap.add_argument("--json")
    a = ap.parse_args()
    if a.selftest: sys.exit(0 if selftest() else 1)
    if not a.nets: ap.error("need --nets or --selftest")
    d = json.load(open(a.nets)); n = d["n"]
    rows = []; groups = {}
    for name, net in d["networks"].items():
        net = [tuple(c) for c in net]
        asc = is_ascending(net); s = sorts_generalized(net, n)
        std = net if asc else untangle(net, n)
        _, csize = comm_class(std)
        k = canon(std, n)
        groups.setdefault(k, []).append(name)
        rows.append({"name": name, "size": len(net), "ascending": asc, "sorts": s,
                     "commutation_class_size": csize,
                     "commutation_lexmin": [list(c) for c in comm_lexmin(std)]})
        print("%-28s size=%2d ascending=%-5s sorts=%-5s commclass=%d"
              % (name, len(net), asc, s, csize), flush=True)
    print("\nsound isomorphism classes: %d" % len(groups))
    for i, (k, names) in enumerate(sorted(groups.items()), 1):
        print("  class %d (%d members): %s" % (i, len(names), ", ".join(sorted(names))))
        print("      canonical: %s" % (list(map(list, k)),))
    if a.json:
        json.dump({"n": n, "tool": "agent-078_sorter_isomorphism_untangle_v1_1",
                   "networks": rows,
                   "classes": [{"members": sorted(v), "canonical": [list(c) for c in k]}
                               for k, v in groups.items()]}, open(a.json, "w"), indent=1)

if __name__ == "__main__":
    main()

