def count_paths(dag):
    from collections import defaultdict
    adj = defaultdict(list)
    for t, s, ij, c in dag["edges"]:
        adj[(t, s)].append((t + 1, c))
    cnt = {(0, dag["levels"][0][0]): 1}
    for t in range(len(dag["levels"]) - 1):
        nc = {}
        for (tt, s), w in cnt.items():
            if tt != t:
                continue
            for e in adj[(t, s)]:
                nc[e] = nc.get(e, 0) + w
        cnt = nc
    return sum(cnt.values())


